App.register({group:'pipeline',label:'06 / AI 自动生产',routes:[{path:'pipeline/board',title:'生产调度中心',icon:'⌁',permission:'pipeline',render(){return UI.page('AI ORCHESTRATION / FLOW','AI 自动生产流水线','从剧本正式版本到镜头生产单元、音视频资产、质检与交付的自动依赖调度。',UI.btn(DB.state.productionStarted?'生产已启动':'启动生产计划','production:start','btn-lime'),`<div class="notice">AI 生产能力中心是系统执行能力，不是人工部门。生产状态、任务依赖和异常恢复在原型中以演示状态展示。</div><div class="card section-gap"><div class="card-head"><div><div class="card-title">端到端生产阶段</div><div class="card-sub">当前项目：${DB.projects.find(x=>x.id===DB.state.projectId)?.title||'雾城来信'}</div></div>${UI.tag(DB.state.productionStarted?'生产运行中':'等待启动',DB.state.productionStarted?'green':'orange')}</div><div class="pipeline">${DB.stages.map((s,i)=>`<div class="stage ${s.state==='done'?'done':''} ${s.state==='active'?'active':''}"><div class="stage-no">STAGE / 0${i+1}</div><div class="stage-name">${s.name}</div><div class="stage-meta">${s.desc}</div><div class="stage-state">${UI.tag(s.state==='done'?'已完成':s.state==='active'?'执行中':'等待依赖',s.state==='done'?'green':s.state==='active'?'lime':'')}</div><div class="tiny muted" style="margin-top:7px">${s.count}</div></div>`).join('')}</div></div><div class="grid grid-2 section-gap"><div class="card"><div class="card-title">任务依赖关系</div><div class="timeline section-gap">${['正式剧本版本 V3','场次与镜头生产单元拆解','人物 / 场景视觉参考锁定','视频镜头生成与质检','配音 / 配乐 / 字幕合成','整集合成与质量检测','人工最终审核与交付'].map((s,i)=>`<div class="timeline-item"><i class="timeline-dot ${i<5?'done':''}"></i><div><div class="timeline-title">${s}</div><div class="timeline-meta">${i<3?'上游已满足':i===3?'部分任务运行中':'等待上游依赖'}</div></div></div>`).join('')}</div></div><div class="card"><div class="card-title">资源与成本观察</div><div class="kpi-line"><span>当前并发任务</span><b>08 / 12</b></div><div class="kpi-line"><span>视频生成队列</span><b>24</b></div><div class="kpi-line"><span>预计剩余成本</span><b>¥1,240</b></div><div class="kpi-line"><span>租户预算余量</span><b>¥32,400</b></div><div class="notice warn section-gap">达到预算阈值或模型不可用时，系统暂停受影响任务并通知员工决策，不静默超额消耗。</div></div></div>`); }},{path:'pipeline/exceptions',title:'异常处置中心',icon:'!',badge:'1',permission:'pipeline',render(){if(DB.state.tenant!=='tn-lab'||DB.state.identity==='employee')return UI.page('AI ORCHESTRATION / EXCEPTIONS','当前租户暂无待处置异常','异常中心仅展示当前租户且当前身份获授权的生产异常。','',`<div class="card">${UI.empty('暂无待处置异常','当前租户没有需要人工决策的异常任务。')}</div>`);return UI.page('AI ORCHESTRATION / EXCEPTIONS','生产异常处置','只将必须人工决策的异常交给员工；恢复后由 AI 继续执行受影响任务。','',`<div class="grid grid-3">${UI.metric('待处置异常','1','受影响任务已暂停','!')}${UI.metric('自动重试成功','14','近 7 天演示记录','↻')}${UI.metric('生产链路完整率','98.4%','不等同于作品质量','✓')}</div><div class="card section-gap"><div class="card-head"><div><div class="card-title">异常事件 · 最后一封语音</div><div class="card-sub mono">EX-26031-02 / SP-26031 / 音频合成</div></div>${UI.tag(DB.state.exceptionResolved?'已恢复':'待人工处置',DB.state.exceptionResolved?'green':'red')}</div><div class="grid grid-2"><div><div class="eyebrow">FAILURE CONTEXT</div><p class="small" style="line-height:1.8">主音频模型连续 3 次返回超时。系统已暂停该音频任务，保留视频、字幕及其他已完成资产，不影响其他项目生产。</p><div class="kpi-line"><span>失败节点</span><b>Voice synthesis</b></div><div class="kpi-line"><span>自动重试次数</span><b>3 / 3</b></div><div class="kpi-line"><span>影响范围</span><b>第 4–6 集对白音频</b></div></div><div><div class="eyebrow">AVAILABLE DECISION</div><div class="callout"><div class="callout-icon">↻</div><div><strong>切换备用模型并恢复任务</strong><p>保持原音色约束，重新生成受影响片段；旧版本资产保留，可追溯。</p></div></div><div class="section-gap">${UI.btn(DB.state.exceptionResolved?'任务已恢复':'确认切换备用模型','exception:resolve','btn-lime')}</div></div></div></div>`); }},{path:'pipeline/shots',title:'镜头生产单元',icon:'▧',permission:'pipeline',render(){return UI.page('AI DIRECTOR / SHOT UNITS','镜头生产单元','Shot Unit 是导演规划与 AI 视频生产之间的核心业务对象。',UI.btn('查看生产调度','go:pipeline/board','btn'),`<div class="grid grid-3">${UI.metric('镜头总量','96','关联正式剧本 V3','▧')}${UI.metric('生成完成','64','已通过镜头质检','✓')}${UI.metric('待生成','32','等待并发资源','◌')}</div><div class="card section-gap"><div class="toolbar"><b class="small">镜头清单 · 第 03 集</b><select class="field" style="width:auto"><option>全部状态</option><option>已完成</option><option>待生成</option></select></div><div class="shot-grid">${['雨夜巷口 · 远景建立','林晚发现录音笔','旧楼走廊 · 跟拍','手机屏幕特写','人物情绪近景','巷口车辆离开'].map((s,i)=>`<article class="shot"><div class="shot-art" style="background:linear-gradient(135deg,${['#647b82,#1b303d','#b3a18c,#4b5051','#7c8c84,#293a3a','#b6b9ae,#414c4d','#9c8b83,#353d48','#74848c,#273640'][i]})"><span>SHOT / 03-${String(i+1).padStart(2,'0')}</span></div><div class="shot-body"><div class="shot-title">${s}</div><div class="shot-meta">${i<4?'4.2s · 已完成 · 质检通过':'6.0s · 等待生成'}</div></div></article>`).join('')}</div></div>`);}}]});
